-- The final, mating action of 282 puzzles without the moves it does not need: a move on a
-- board that needed none (an inactive timeline, one ahead of the present) dropped whenever the
-- action stays legal and still mates (checked with the rules core). "newTimeline" is dropped
-- where the trimmed line creates no timeline any more. Ratings and plays are kept.
update public.puzzles q
   set solution = x->'solution', steps = x->'steps', themes = array(select jsonb_array_elements_text(x->'themes'))
  from jsonb_array_elements($trim$
